{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 도시공원 조례상 녹지 가로지르는 진입도로 점용허가의 폭과 진입로 간 거리 기준",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "진입도로의 규모는 원칙적으로 폭 8미터 이하로 하되, 그 이상이 필요한 경우에는 「국토의 계획 및 이용에 관한 법률」 및 「사도법」에 따른 도로(영 제22조제3호에 따른 도로)로 점용허가하여야 합니다. 도로변 녹지를 가로지르는 진입도로 간의 최소거리는 250미터 이상으로 하여야 합니다. 다만, 현지여건상 불가피하거나 교통의 원활한 소통을 위하여 진출입구의 분리가 필요한 경우에는 그러하지 아니합니다.",
          "b_ids": "도시공원:제12조제2호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
